        public string MemberKey { get; set; } = ""; public string Name { get; set; } = ""; public string Category { get; set; } = ""; public string DeclaringType { get; set; } = ""; public string DeclaredType { get; set; } = ""; public string Visibility { get; set; } = ""; public bool Readable { get; set; } public IReadOnlyList<AttributeInfo> Attributes { get; set; } = new List<AttributeInfo>(); public PathSegment? PathSegment { get; set; } public JsonObjectNode? Dependency { get; set; } public string? Reason { get; set; } public string? WrapperKey { get; set; } public string? CompatibilityAlias { get; set; }
